changeSet.sql:
ALTER TABLE plots DROP CONSTRAINT chk_plots_status;
ALTER TABLE plots ADD CONSTRAINT chk_plots_status
    CHECK (status IN ('AVAILABLE_DEV', 'AVAILABLE_INV', 'RESERVED', 'SOLD', 'WITHHELD'));

ALTER TABLE plots ADD COLUMN withheld_from_status varchar(32);
ALTER TABLE plots ADD CONSTRAINT chk_plots_withheld_from_status
    CHECK (withheld_from_status IS NULL
           OR (status = 'WITHHELD' AND withheld_from_status IN ('AVAILABLE_DEV', 'AVAILABLE_INV')));
COMMENT ON COLUMN plots.withheld_from_status IS
    'The available variant a WITHHELD plot returns to. Null whenever the plot is not withheld.';

changeSet.rollback:
ALTER TABLE plots DROP CONSTRAINT chk_plots_withheld_from_status;
ALTER TABLE plots DROP COLUMN withheld_from_status;
ALTER TABLE plots DROP CONSTRAINT chk_plots_status;
ALTER TABLE plots ADD CONSTRAINT chk_plots_status
    CHECK (status IN ('AVAILABLE_DEV', 'AVAILABLE_INV', 'RESERVED', 'SOLD'));

changeSet.sql:
ALTER TABLE price_tiers ADD COLUMN retired_at timestamp(6) with time zone;
COMMENT ON COLUMN price_tiers.retired_at IS
    'Set when the tier stops accepting new plots. Existing plots keep it. Never the same as deleted.';

ALTER TABLE plots DROP CONSTRAINT uq_plots_estate_block_number;
CREATE UNIQUE INDEX uq_plots_estate_block_number
    ON plots (estate_id, block_id, plot_number) NULLS NOT DISTINCT
    WHERE deleted = false;

changeSet.rollback:
DROP INDEX uq_plots_estate_block_number;
ALTER TABLE plots ADD CONSTRAINT uq_plots_estate_block_number
    UNIQUE NULLS NOT DISTINCT (estate_id, block_id, plot_number);
